# Clean version: components of rare cells, 4-dir connectivity.
def comps(n):
    Ia=np.array(G[f'Demo pair {n} input']); Oa=np.array(G[f'Demo pair {n} output'])
    c=Counter(Ia.flatten().tolist()); b,f=c.most_common(2)[0][0],c.most_common(2)[1][0]
    mk=(Ia!=b)&(Ia!=f)
    vis=[[False]*7 for _ in range(7)]; ms=[]
    for r in range(7):
        for cc in range(7):
            if mk[r,cc] and not vis[r][cc]:
                stack=[(r,cc)]; comp=[]; vis[r][cc]=True
                while stack:
                    rr,ccc=stack.pop(); comp.append((rr,ccc))
                    for dr_,dc_ in ((1,0),(-1,0),(0,1),(0,-1)):
                        nr,nc=rr+dr_,ccc+dc_
                        if 0<=nr<7 and 0<=nc<7 and mk[nr,nc] and not vis[nr][nc]:
                            vis[nr][nc]=True; stack.append((nr,nc))
                ms.append(comp)
    o=[[int(Oa[i,j]==8) for j in range(3)] for i in range(3)]
    return ms,o
for n in range(1,8):
    ms,o=comps(n)
    print('demo',n,'out:',o)
    for comp in ms: print('   ',comp)
